// boundary middleware inserts a typed extension; the handler extracts it
async fn list_orders(
    Extension(principal): Extension<Principal>,
) -> Result<Json<Vec<Order>>, StatusCode> {
    ensure(&principal, "orders:read").map_err(|_| StatusCode::FORBIDDEN)?;
    Ok(Json(orders_for(&principal).await))
}

